        + 3 * size_of::<Result<(), super::Diagnostic>>()
        + 2 * size_of::<std::slice::Iter<'static, (Label, SharedWeighted)>>()
        + 2 * size_of::<&Vec<(Label, SharedWeighted)>>()
        + size_of::<&[(Label, SharedWeighted)]>();
